CREATE POLICY tenant_isolation ON card_velocity_counter USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_card_velocity_counter_touch BEFORE UPDATE ON card_velocity_counter FOR EACH ROW EXECUTE FUNCTION touch_row();

-- card_authorization_rule: Program or tenant level authorisation rule (beyond card controls), e.g. velocity or risky MCC step-up
CREATE TABLE card_authorization_rule (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  card_program_id              uuid,
  name                         varchar(120) NOT NULL,
  priority                     integer NOT NULL DEFAULT 100,
  condition_expression         text NOT NULL,
  action                       varchar(40) NOT NULL CHECK (action IN ('APPROVE', 'DECLINE', 'REVIEW', 'STEP_UP')),
  decline_reason               varchar(40) CHECK (decline_reason IN ('INSUFFICIENT_FUNDS', 'CARD_INACTIVE', 'CARD_FROZEN', 'CARD_EXPIRED', 'INVALID_PIN', 'PIN_TRIES_EXCEEDED', 'CONTROL_MCC', 'CONTROL_MERCHANT', 'CONTROL_COUNTRY', 'CONTROL_CHANNEL', 'LIMIT_EXCEEDED', 'VELOCITY_EXCEEDED', 'FRAUD_SUSPECTED', 'JIT_DECLINED', 'JIT_TIMEOUT', 'INVALID_CVV', 'INVALID_EXPIRY', 'THREEDS_FAILED', 'SYSTEM_ERROR', 'OTHER', 'CARD_LOST', 'CARD_STOLEN', 'CARD_BLOCKED', 'PROGRAM_SUSPENDED', 'RULE_DECLINED', 'CONTROL_AMOUNT', 'CONTROL_TIME', 'CONTROL_CURRENCY', 'ORIGINAL_NOT_FOUND')),
  is_active                    boolean NOT NULL DEFAULT true,
  valid_from                   timestamptz,
  valid_to                     timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE card_authorization_rule IS 'Program or tenant level authorisation rule (beyond card controls), e.g. velocity or risky MCC step-up';
COMMENT ON COLUMN card_authorization_rule.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN card_authorization_rule.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN card_authorization_rule.created_at IS 'Creation time';
COMMENT ON COLUMN card_authorization_rule.created_by IS 'Principal that created the row';
COMMENT ON COLUMN card_authorization_rule.updated_at IS 'Last update time';
COMMENT ON COLUMN card_authorization_rule.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN card_authorization_rule.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN card_authorization_rule.card_program_id IS 'Program (empty = all programs)';
COMMENT ON COLUMN card_authorization_rule.name IS 'Rule name';
COMMENT ON COLUMN card_authorization_rule.priority IS 'Lower evaluates first';
COMMENT ON COLUMN card_authorization_rule.condition_expression IS 'Expression over the authorisation context (CEL subset: == != < <= > >= in [..] && || ! and parentheses over amount, currency, mcc, merchant_id, merchant_country, channel, pos_entry_mode, is_international, card_present, hour, fraud_score), e.g. mcc in [''7995''] && amount > 500';
COMMENT ON COLUMN card_authorization_rule.action IS 'Action when the condition is true';
COMMENT ON COLUMN card_authorization_rule.decline_reason IS 'Decline reason when action is DECLINE';
COMMENT ON COLUMN card_authorization_rule.is_active IS 'Active';
COMMENT ON COLUMN card_authorization_rule.valid_from IS 'Start';
COMMENT ON COLUMN card_authorization_rule.valid_to IS 'End';
COMMENT ON COLUMN card_authorization_rule.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN card_authorization_rule.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN card_authorization_rule.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN card_authorization_rule.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN card_authorization_rule.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_card_authorization_rule_tenant ON card_authorization_rule (tenant_id, created_at);
CREATE INDEX ix_card_authorization_rule_card_program_id ON card_authorization_rule (card_program_id);
ALTER TABLE card_authorization_rule ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON card_authorization_rule USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_card_authorization_rule_touch BEFORE UPDATE ON card_authorization_rule FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA card_auth TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA card_auth TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA card_auth GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
